def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]
    if n == 1:
        return 'C'

    my_d_total = 0
    opp_c_total = 0
    for p in history:
        if p[0] == 'D':
            my_d_total += 1
        if p[1] == 'C':
            opp_c_total += 1

    wlen = n if n < 12 else 12
    opp_c_recent = 0
    for p in history[-wlen:]:
        if p[1] == 'C':
            opp_c_recent += 1
    base = (opp_c_recent + 1.0) / (wlen + 2.0)

    ac_c = 0
    ac_t = 0
    ad_c = 0
    ad_t = 0
    for i in range(1, n):
        age = n - 1 - i
        if age >= 30:
            continue
        if age < 5:
            w = 4
        elif age < 15:
            w = 2
        else:
            w = 1

        prev_me = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_me == 'C':
            ac_t += w
            if cur_opp == 'C':
                ac_c += w
        else:
            ad_t += w
            if cur_opp == 'C':
                ad_c += w

    ac_d = ac_t - ac_c
    ad_d = ad_t - ad_c
    total_t = ac_t + ad_t

    if total_t > 0:
        match = (ac_c + ad_d) / (total_t + 1.0)
    else:
        match = 0.0
    if match > 1.0:
        match = 1.0
    if match < 0.0:
        match = 0.0

    pc = (ac_c + 2.0 * base + 0.5) / (ac_t + 3.0)
    if pc > 1.0:
        pc = 1.0
    if pc < 0.0:
        pc = 0.0

    pd = (ad_c + 0.25 * base + 0.05) / (ad_t + 1.0)
    if pd > 1.0:
        pd = 1.0
    if pd < 0.0:
        pd = 0.0

    diff = pc - pd
    if diff < 0.0:
        diff = 0.0

    last_ind = 1.0 if last_opp == 'C' else 0.0
    if total_t < 1:
        q_mode = base
    else:
        copy_pred = pc if last_me == 'C' else pd
        q_mode = match * copy_pred + (1.0 - match) * base

    q = 0.5 * last_ind + 0.5 * q_mode
    if q > 1.0:
        q = 1.0
    if q < 0.0:
        q = 0.0

    streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_d += 1
        i -= 1

    wlen2 = n if n < 10 else 10
    opp_d_recent = 0
    for p in history[-wlen2:]:
        if p[1] == 'D':
            opp_d_recent += 1
    recent_d_rate = opp_d_recent / wlen2 if wlen2 else 0.0

    defensive = False
    if recent_d_rate >= 0.7:
        defensive = True
    if opp_c_total * 4 <= n:
        defensive = True
    if streak_d >= 6 and base < 0.65:
        defensive = True
    if q < 0.2 and streak_d >= 3 and base < 0.8:
        defensive = True

    retaliator = False
    if match >= 0.62 and pc >= 0.70 and pd <= 0.45 and base >= 0.65:
        retaliator = True
    if ad_t >= 1 and ad_d >= 1 and pc >= 0.60 and base >= 0.50:
        if ad_d >= ad_c or diff >= 0.45:
            retaliator = True

    exploitable = False
    if (not retaliator) and pd >= 0.55 and diff <= 0.45 and base >= 0.55:
        exploitable = True
    if (not retaliator) and ad_c >= 2 and ad_c >= ad_d and pd >= 0.50:
        exploitable = True

    if my_d_total == 0 and base >= 0.75 and last_opp == 'C' and n < 95:
        if n == 5 or rng.random() < 0.02:
            return 'D'

    if retaliator:
        if last_opp == 'D':
            if last_me == 'D':
                return 'C'
            if streak_d >= 5 or recent_d_rate >= 0.5:
                return 'D'
            return 'C'
        return 'C'

    if defensive:
        return 'D'

    if exploitable:
        return 'D'

    if n == 98 and diff < 0.55:
        return 'D'

    if recent_d_rate >= 0.55 and q < 0.45:
        return 'D'

    gain = 1.0 + q
    penalty = 3.8 * diff
    if gain > penalty:
        return 'D'

    return 'C'
